  "schemaVersion": 1,
  "characterId": "cen",
  "lastUpdatedChapterRef": "chapter:chapter-003.md",
  "factsKnown": [
    {
      "id": "cen-initial",
      "summary": "知道议事厅今夜要收走蓝签账页；不知道藏处，不知道密道口令",
      "sourceChapterRef": "chapter:chapter-001.md"
    },
    {
      "summary": "听见林岚称20:35钟声来源未核，苏砚将其记为未核；船继续正航道，何芷承诺先送药后谈账页。",
      "id": "257a8f08-40ac-4756-a824-05948b8f8749"
    }
  ],
  "emotionalMemory": [
    {
      "summary": "何芷拒绝承诺交账页，使他感到交接仍可能失控。",
      "id": "52077813-44f3-4f1d-8292-8893c11dde3e"
    }
  ],
  "relationshipDeltas": [
    {
      "summary": "对何芷的试探未获结果，但接受她先救病人的顺序。",
      "id": "bab6b6c7-da19-442e-bd47-94ad3ce9f789"
    }
  ],
  "unresolvedIntentions": [
    {
      "id": "cen-goal",
      "summary": "阻止旧账公开但不伤及病人"
    },
    {
      "summary": "抵达后仍要促成账页交接，同时避免妨碍病人用药。",
      "id": "d443780a-3bb4-4198-bbef-78e6e82498f4"
    }
  ],
  "privateMisbeliefs": []
}

sourceSnapshots.character-memory:he:
{
  "schemaVersion": 1,
  "characterId": "he",
  "lastUpdatedChapterRef": "chapter:chapter-003.md",
  "factsKnown": [
    {
      "id": "he-initial",
      "summary": "仅她知道药箱暗格有蓝签账页；她尚未透露",
      "sourceChapterRef": "chapter:chapter-001.md"
    },
    {
      "summary": "船于20:20离岸，叶澄检查确认底板未进水、桶箍松动并固定；六人继续走正规航道。",
      "id": "fe0e9b11-124c-49a6-96b2-94dd1daf772f"
    }
  ],
  "emotionalMemory": [
    {
      "summary": "陆行舟实际修好松桶后，她稍减戒心；岑寂仍让她警惕。",
      "id": "b74b5f68-a59b-47e1-8a6c-da347de8d1d0"
    }
  ],
  "relationshipDeltas": [
    {
      "summary": "认可叶澄继续掌舵，也接受陆行舟以行动而非辩解证明谨慎。",
      "id": "94509d51-8512-4d76-ba95-410371331a19"
    }
  ],
  "unresolvedIntentions": [
    {
      "id": "he-goal",
      "summary": "把冷藏药送到灯塔诊所"
    },
    {
      "summary": "先将药送达并核验封铅药单，再决定如何处理账页。",
      "id": "6f322b81-3cfa-44b9-8d70-93aefe9c1b08"
    }
  ],
  "privateMisbeliefs": []
}

sourceSnapshots.character-memory:lu:
{
  "schemaVersion": 1,
  "characterId": "lu",
  "lastUpdatedChapterRef": "chapter:chapter-003.md",
  "factsKnown": [
    {
      "id": "lu-initial",
      "summary": "知道自己没有换过钟芯；不知道慢了几分钟",
      "sourceChapterRef": "chapter:chapter-001.md"
    },
    {
      "summary": "船底异响来自舱内松动木桶而非已见漏水；他当众绑紧桶箍，众人看见。",
      "id": "c5b4b5b6-5d95-40f5-9ea9-ab9555825d79"
    }
  ],
  "emotionalMemory": [
    {
      "summary": "被限制检查令他不快，但修好松桶后得到继续留在船上的位置。",
      "id": "0d9a47ca-4b97-4d59-ab6b-963b89a13d93"
    }
  ],
  "relationshipDeltas": [
    {
      "summary": "以实际修理回应苏砚的怀疑，暂获有限信任。",
      "id": "0f170839-fa91-4e25-b398-527269f153f0"
    }
  ],
  "unresolvedIntentions": [
    {
      "id": "lu-goal",
      "summary": "修好潮钟并洗清偷芯嫌疑"
    },
    {
      "summary": "继续观察船况，也想找机会说明自己未换钟芯。",
      "id": "21a2082f-7b1c-4522-ac52-509b6dae8c93"
    }
  ],
  "privateMisbeliefs": []
}

sourceSnapshots.character-memory:ye:
{
  "schemaVersion": 1,
  "characterId": "ye",
  "lastUpdatedChapterRef": "chapter:chapter-003.md",
  "factsKnown": [
    {
      "id": "ye-initial",
      "summary": "知道低潮碎石滩危险、渡口至灯塔航程四十分钟；不知道暗格和七分钟",
      "sourceChapterRef": "chapter:chapter-001.md"
    },
    {
      "summary": "20:24发现异响后确认是舱内松桶，底板未进水；低潮后仍坚持正规航道，不缩短四十分钟航程。",
      "id": "a1262491-f592-4d28-b522-b6a2a8a9db18"
    }
  ],
  "emotionalMemory": [
    {
      "summary": "松桶固定后对船况稍安心，但仍不接受他人催促或替她判断航向。",
      "id": "329ab551-cb1d-453b-90a2-646566fe90b7"
    }
  ],
  "relationshipDeltas": [
    {
      "summary": "接受陆行舟修理桶箍，保持对何芷的旧有人情但不让其影响船舶安全。",
      "id": "3a63b444-b12d-44a5-b1bb-bd2f96c4522f"
    }
  ],
  "unresolvedIntentions": [
    {
      "id": "ye-goal",
      "summary": "保住执照与船员"
    },
    {
      "summary": "继续掌舵并留意任何新异响，必要时靠岸检查。",
      "id": "73256c58-5d0d-4763-9490-9fdc09898126"
    }
  ],
  "privateMisbeliefs": []
}

